/// The first whole minute at or after `seconds`. A time already on the minute is itself.
pub(super) fn next_whole_minute(seconds: u64) -> u64 {
    seconds.div_ceil(60).saturating_mul(60)
}

pub(super) async fn resolve_time_window(
    state: &AppState,
    explicit: Option<&PlanningHorizonBody>,
    now: u64,
) -> Result<TimeWindowBody> {
    if let Some(explicit) = explicit {
        let invalid = || {
            AppError::bad_request_diagnostic(
                "invalid_horizon",
                "horizon requires RFC 3339 timestamps with start before end",
            )
        };
        let start = timestamp_seconds(&explicit.start).map_err(|_| invalid())?;
        let end = timestamp_seconds(&explicit.end).map_err(|_| invalid())?;
        if start >= end {
            return Err(invalid());
        }
        return Ok(TimeWindowBody { start, end });
    }
    let pool = state.inner().store.pool();
    let row = sqlx::query(
        "SELECT window_start, window_end, payload_json FROM calendars
        ORDER BY created_at DESC
        LIMIT 1",
    )
    .fetch_optional(pool)
    .await
    .map_err(|e| AppError::Internal(e.to_string()))?;

    if let Some(row) = row {
        let window_start: String = row
            .try_get("window_start")
            .map_err(|e| AppError::Internal(e.to_string()))?;
        let window_end: String = row
            .try_get("window_end")
            .map_err(|e| AppError::Internal(e.to_string()))?;
        let start = timestamp_seconds(&window_start)?;
        let end = timestamp_seconds(&window_end)?;
        if start < end {
            return Ok(TimeWindowBody { start, end });
        }
    }

    Ok(TimeWindowBody {
        start: now,
        end: now.saturating_add(state.inner().planning_horizon_seconds),
    })
}

fn timestamp_seconds(value: &str) -> Result<u64> {
    let timestamp = UbuTimestamp::parse(value)
        .map_err(|e| AppError::bad_request_diagnostic("invalid_calendar_window", e.to_string()))?;
    let seconds = timestamp.inner().unix_timestamp();
    if seconds < 0 {
        return Err(AppError::bad_request_diagnostic(
            "invalid_calendar_window",
            "calendar windows before Unix epoch are not supported by the Phase A planner adapter",
        ));
    }
    Ok(seconds as u64)
}

fn task_graph(
    tasks: &[TaskSpecBody],
    priorities: &BTreeMap<String, u32>,
    deadlines: &HashMap<String, u64>,
    mandatory: &HashSet<String>,
) -> Result<TaskGraphBody> {
    let key = |id: &String| {
        (
            if mandatory.contains(id) { 0 } else { 1 },
            priorities.get(id).copied().unwrap_or(0),
            deadlines.get(id).copied().unwrap_or(u64::MAX),
            id.clone(),
        )
    };
    let mut children: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
    let mut indegree: BTreeMap<String, usize> = BTreeMap::new();
    let mut edges = Vec::new();
    for task in tasks {
        indegree.entry(task.id.clone()).or_insert(0);
        children.entry(task.id.clone()).or_default();
        for dependency in &task.depends_on {
            children
                .entry(dependency.clone())
                .or_default()
                .insert(task.id.clone());
            *indegree.entry(task.id.clone()).or_insert(0) += 1;
            edges.push(TaskGraphEdgeBody {
                before: dependency.clone(),
                after: task.id.clone(),
            });
//! Pure, transient duration evidence from explicitly recorded routine execution.
use std::collections::BTreeMap;

use crate::api::planning::DurationEstimateBody;

/// Fewer than five completed observations cannot support a trustworthy spread.
pub const MINIMUM_OBSERVATIONS: usize = 5;
/// Older observations no longer describe how the routine goes now.
pub const OBSERVATION_WINDOW_SECONDS: i64 = 90 * 24 * 60 * 60;
/// Exclude forgotten timers without trimming away a fixed fraction of the genuine tail.
pub const OUTLIER_MULTIPLE: u64 = 8;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Observation {
    pub started_at: i64,
    pub completed_at: i64,
}
impl Observation {
    pub fn seconds(&self) -> i64 {
        self.completed_at.saturating_sub(self.started_at)
    }
    fn usable(&self) -> bool {
        self.completed_at > self.started_at
    }
}

#[derive(Debug, PartialEq, Eq)]
pub enum Untrusted {
    TooFewObservations(usize),
}

#[derive(Debug, PartialEq, Eq)]
pub struct DerivedDuration {
    pub estimate: DurationEstimateBody,
    pub observations: usize,
    pub min_seconds: u64,
    pub mode_seconds: u64,
    pub p95_seconds: u64,
}

/// Nearest-rank percentile of a nonempty, sorted list of positive durations.
pub fn percentile(sorted: &[i64], fraction: f64) -> u64 {
    assert!(!sorted.is_empty());
    let rank = (sorted.len() as f64 * fraction).ceil() as usize;
    sorted[rank.saturating_sub(1).min(sorted.len() - 1)] as u64
}

pub fn derive(observations: &[Observation]) -> Result<DerivedDuration, Untrusted> {
    let mut seconds: Vec<_> = observations
        .iter()
        .filter(|o| o.usable())
        .map(Observation::seconds)
        .collect();
    if seconds.len() < MINIMUM_OBSERVATIONS {
        return Err(Untrusted::TooFewObservations(seconds.len()));
    }
    seconds.sort_unstable();
    let ceiling = percentile(&seconds, 0.5).saturating_mul(OUTLIER_MULTIPLE);
    seconds.retain(|&seconds| seconds as u64 <= ceiling);
    if seconds.len() < MINIMUM_OBSERVATIONS {
        return Err(Untrusted::TooFewObservations(seconds.len()));
    }
    let min_seconds = seconds[0] as u64;
    let mut mode_seconds = percentile(&seconds, 0.5);
    let mut p95_seconds = percentile(&seconds, 0.95);
    let estimate = if min_seconds == p95_seconds {
        DurationEstimateBody::Fixed {
            seconds: min_seconds,
        }
    } else {
        // Tied order statistics need one-second nudges for the schema's strict ordering.
        mode_seconds = mode_seconds.max(min_seconds + 1);
        p95_seconds = p95_seconds.max(mode_seconds + 1);
        DurationEstimateBody::ShiftedLognormalP95 {
            min_seconds,
            mode_seconds,
            p95_seconds,
        }
    };
    Ok(DerivedDuration {
        estimate,
        observations: seconds.len(),
        min_seconds,
        mode_seconds,
        p95_seconds,
    })
}

/// Starts replace an open start; only a following completion closes an observation.
pub fn pair(mut events: Vec<(i64, bool)>) -> Vec<Observation> {
    events.sort_unstable_by_key(|&(time, start)| (time, std::cmp::Reverse(start)));
    let mut open = None;
    let mut observations = Vec::new();
    for (time, start) in events {
        if start {
            open = Some(time);
        } else if let Some(started_at) = open.take() {
            observations.push(Observation {
                started_at,
                completed_at: time,
            });
        }
    }
    observations
}

/// Both ends must lie in the inclusive recent window; future events are excluded.
pub fn by_group(rows: Vec<(String, i64, bool)>, now: i64) -> BTreeMap<String, Vec<Observation>> {
    let mut groups = BTreeMap::<String, Vec<(i64, bool)>>::new();
    let since = now.saturating_sub(OBSERVATION_WINDOW_SECONDS);
    for (group, time, start) in rows {
        if time >= since && time <= now {
            groups.entry(group).or_default().push((time, start));
        }
    }
    groups
        .into_iter()
        .map(|(group, events)| (group, pair(events)))
        .collect()
}

